const issueAuthToken = async (db: Awaited<ReturnType<typeof ensureDb>>, userId: number, purpose: "EMAIL_VERIFY" | "PASSWORD_RESET") => { const token = createOpaqueToken(); await db.delete(authTokens).where(and(eq(authTokens.userId, userId), eq(authTokens.purpose, purpose), isNull(authTokens.consumedAt))); await db.insert(authTokens).values({ userId, purpose, tokenHash: hashOpaqueToken(token), expiresAt: new Date(Date.now() + 60 * 60 * 1000) }); return token; };
const lockoutError = (retryAt: Date) => new TRPCError({ code: "TOO_MANY_REQUESTS", message: "For your security, please wait before trying again.", cause: { retryAt: retryAt.toISOString() } });
const accountRateLimitedProcedure = (scope: string, limit: number, windowSeconds: number, lockSeconds: number) => protectedProcedure.use(async ({ ctx, next }) => { const redisDecision = await consumeSecurityLimit({ scope, identifier: String(ctx.user.id), limit, windowSeconds, lockSeconds }); if (redisDecision) { if (redisDecision.limited && redisDecision.retryAt) { const db = await ensureDb(); await db.insert(auditLogs).values({ actorUserId: ctx.user.id, action: "SECURITY_RATE_LIMITED", targetType: "USER", targetId: String(ctx.user.id), metadata: { scope, stateSource: "redis" } }); throw lockoutError(redisDecision.retryAt); } return next({ ctx }); } const db = await ensureDb(); const now = new Date(); const rateKey = `security:${hashOpaqueToken(`${scope}:${ctx.user.id}`).slice(0, 56)}`; const rows = await db.select().from(authRateLimits).where(eq(authRateLimits.rateKey, rateKey)).limit(1); const current = rows[0]; if (!current) await db.insert(authRateLimits).values({ rateKey, attempts: 1, windowStartedAt: now }); else if (current.blockedUntil && current.blockedUntil > now) throw lockoutError(current.blockedUntil); else if (current.windowStartedAt.getTime() + windowSeconds * 1_000 <= now.getTime()) await db.update(authRateLimits).set({ attempts: 1, windowStartedAt: now, blockedUntil: null }).where(eq(authRateLimits.id, current.id)); else if (current.attempts >= limit) { const blockedUntil = new Date(now.getTime() + lockSeconds * 1_000); await db.update(authRateLimits).set({ blockedUntil }).where(eq(authRateLimits.id, current.id)); await db.insert(auditLogs).values({ actorUserId: ctx.user.id, action: "SECURITY_RATE_LIMITED", targetType: "USER", targetId: String(ctx.user.id), metadata: { scope, stateSource: "database_fallback" } }); throw lockoutError(blockedUntil); } else await db.update(authRateLimits).set({ attempts: current.attempts + 1 }).where(eq(authRateLimits.id, current.id)); return next({ ctx }); });
const onboardingSubmissionProcedure = accountRateLimitedProcedure("seller-onboarding", 8, 60 * 60, 60 * 60);
