const authThrottledProcedure = publicProcedure.use(async ({ ctx, path, next }) => { const forwarded = ctx.req.headers["x-forwarded-for"]; const clientIp = typeof forwarded === "string" ? forwarded.split(",")[0].trim() : ctx.req.ip ?? "unknown"; const redisDecision = await consumeSecurityLimit({ scope: `endpoint:${path}`, identifier: clientIp, limit: 10, windowSeconds: 15 * 60, lockSeconds: 15 * 60 }); if (redisDecision) { if (redisDecision.limited && redisDecision.retryAt) throw lockoutError(redisDecision.retryAt); return next({ ctx }); } const db = await ensureDb(); const now = new Date(); const rateKey = `auth:${hashOpaqueToken(`${path}:${clientIp}`).slice(0, 56)}`; const rows = await db.select().from(authRateLimits).where(eq(authRateLimits.rateKey, rateKey)).limit(1); const current = rows[0]; const windowMs = 15 * 60 * 1000; const maxAttempts = 10; if (!current) await db.insert(authRateLimits).values({ rateKey, attempts: 1, windowStartedAt: now }); else if (current.blockedUntil && current.blockedUntil > now) throw lockoutError(current.blockedUntil); else if (current.windowStartedAt.getTime() + windowMs <= now.getTime()) await db.update(authRateLimits).set({ attempts: 1, windowStartedAt: now, blockedUntil: null }).where(eq(authRateLimits.id, current.id)); else if (current.attempts >= maxAttempts) { const blockedUntil = new Date(now.getTime() + windowMs); await db.update(authRateLimits).set({ blockedUntil }).where(eq(authRateLimits.id, current.id)); throw lockoutError(blockedUntil); } else await db.update(authRateLimits).set({ attempts: current.attempts + 1 }).where(eq(authRateLimits.id, current.id)); return next({ ctx }); });
const authenticatedAuthThrottledProcedure = authThrottledProcedure.use(async ({ ctx, next }) => { if (!ctx.user) throw new TRPCError({ code: "UNAUTHORIZED", message: "Sign in to manage your account security." }); return next({ ctx: { ...ctx, user: ctx.user } }); });
