const storeVerificationEvidence = async (userId: number, evidence: z.infer<typeof verificationEvidenceSchema>) => { const marker = `data:${evidence.mimeType};base64,`; if (!evidence.dataUrl.startsWith(marker)) throw new TRPCError({ code: "BAD_REQUEST", message: "Evidence file data is invalid." }); const bytes = Buffer.from(evidence.dataUrl.slice(marker.length), "base64"); if (!bytes.length || bytes.length > 5 * 1024 * 1024) throw new TRPCError({ code: "PAYLOAD_TOO_LARGE", message: "Evidence files must be 5 MB or smaller." }); const safeName = evidence.filename.replace(/[^a-zA-Z0-9._-]/g, "_"); return storagePut(`verification-evidence/${userId}/${crypto.randomUUID()}-${safeName}`, bytes, evidence.mimeType); };
const caseEvidenceInput = z.object({ filename: z.string().trim().min(1).max(180), mimeType: z.enum(["image/jpeg", "image/png", "image/webp", "video/mp4", "video/webm"]), dataUrl: z.string().min(32).max(14_000_000) });
const caseEvidenceMatchesSignature = (mimeType: z.infer<typeof caseEvidenceInput>["mimeType"], bytes: Buffer) => {
  if (mimeType === "image/jpeg") return bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff;
  if (mimeType === "image/png") return bytes.length >= 8 && bytes.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
  if (mimeType === "image/webp") return bytes.length >= 12 && bytes.subarray(0, 4).toString("ascii") === "RIFF" && bytes.subarray(8, 12).toString("ascii") === "WEBP";
  if (mimeType === "video/mp4") return bytes.length >= 12 && bytes.subarray(4, 8).toString("ascii") === "ftyp";
  return bytes.length >= 4 && bytes.subarray(0, 4).equals(Buffer.from([0x1a, 0x45, 0xdf, 0xa3]));
};
const storeCaseEvidence = async (userId: number, caseKind: "dispute" | "report", caseId: number, evidence: z.infer<typeof caseEvidenceInput>) => {
  const marker = `data:${evidence.mimeType};base64,`;
  if (!evidence.dataUrl.startsWith(marker)) throw new TRPCError({ code: "BAD_REQUEST", message: "Evidence file data is invalid." });
  const bytes = Buffer.from(evidence.dataUrl.slice(marker.length), "base64");
  const maxBytes = evidence.mimeType.startsWith("video/") ? 10 * 1024 * 1024 : 3 * 1024 * 1024;
  if (!bytes.length || bytes.length > maxBytes) throw new TRPCError({ code: "PAYLOAD_TOO_LARGE", message: evidence.mimeType.startsWith("video/") ? "Case videos must be 10 MB or smaller." : "Case photos must be 3 MB or smaller." });
  if (!caseEvidenceMatchesSignature(evidence.mimeType, bytes)) throw new TRPCError({ code: "BAD_REQUEST", message: "Evidence content does not match its declared file type." });
  const safeName = evidence.filename.replace(/[^a-zA-Z0-9._-]/g, "_");
  return storagePut(`case-evidence/${caseKind}/${caseId}/${userId}/${crypto.randomUUID()}-${safeName}`, bytes, evidence.mimeType);
};
