export const assessListingPublication = ({ title, description, priceKobo, availableUnits, hasActiveCategory, images }: { title: string; description: string; priceKobo: number; availableUnits: number; hasActiveCategory: boolean; images: Array<{ mimeType: string | null; sizeBytes: number | null }> }) => { const validationErrors: string[] = []; if (title.trim().length < 3) validationErrors.push("Add a product title of at least three characters."); if (description.trim().length < 20) validationErrors.push("Add a product description of at least twenty characters."); if (priceKobo <= 0) validationErrors.push("Set a price greater than zero."); if (availableUnits <= 0) validationErrors.push("Add positive available stock before publishing."); if (!hasActiveCategory) validationErrors.push("Select an active marketplace category."); if (!images.length) validationErrors.push("Add at least one product image before publishing."); const invalidImageCount = images.filter(image => !image.mimeType || !["image/jpeg", "image/png", "image/webp"].includes(image.mimeType) || !image.sizeBytes || image.sizeBytes <= 0 || image.sizeBytes > 4 * 1024 * 1024).length; return { validationErrors, invalidImageCount, outcome: validationErrors.length ? null : invalidImageCount ? "FLAGGED" as const : "ACTIVE" as const }; };
