export const reminderTime = (input: z.infer<typeof reminderInput>, now = new Date()) => { const delay = input.reminderType === "TOMORROW" ? 24 * 60 * 60 * 1_000 : input.reminderType === "THREE_DAYS" ? 3 * 24 * 60 * 60 * 1_000 : input.reminderType === "ONE_WEEK" ? 7 * 24 * 60 * 60 * 1_000 : null; const scheduledFor = delay === null ? input.scheduledFor : new Date(now.getTime() + delay); if (!scheduledFor || scheduledFor.getTime() <= now.getTime() + 60_000) throw new TRPCError({ code: "BAD_REQUEST", message: "Choose a reminder time at least one minute from now." }); return scheduledFor; };
