const getAdminSecurityAlerts = async (db: Awaited<ReturnType<typeof ensureDb>>) => { const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000); const rows = await db.select({ audit: auditLogs, actor: { id: users.id, name: users.name, email: users.email, role: users.role } }).from(auditLogs).leftJoin(users, eq(auditLogs.actorUserId, users.id)).where(gte(auditLogs.createdAt, since)); const safeRows = (rows as any[]).filter(row => row?.audit?.action && row?.audit?.createdAt instanceof Date); safeRows.sort((left, right) => right.audit.createdAt.getTime() - left.audit.createdAt.getTime()); const alerts: Array<{ type: "REPEATED_FAILURE" | "ROLE_CHANGE"; severity: "HIGH" | "MEDIUM"; action: string; message: string; count: number; actor: { id: number | null; name: string | null; email: string | null; role: string | null } | null; firstAt: Date; lastAt: Date }> = []; const failureGroups = new Map<string, typeof safeRows>(); for (const row of safeRows) { if (!row.audit.action.includes("FAILED")) continue; const key = `${row.audit.actorUserId ?? "unknown"}:${row.audit.action}`; const group = failureGroups.get(key) ?? []; group.push(row); failureGroups.set(key, group); } failureGroups.forEach(group => { if (group.length < 5) return; const first = group[group.length - 1]; const latest = group[0]; alerts.push({ type: "REPEATED_FAILURE", severity: "HIGH", action: latest.audit.action, message: `${group.length} repeated failed actions detected in the last 7 days.`, count: group.length, actor: latest.actor, firstAt: first.audit.createdAt, lastAt: latest.audit.createdAt }); }); for (const row of safeRows) { if (row.audit.action !== "USER_ROLE_CHANGED") continue; alerts.push({ type: "ROLE_CHANGE", severity: "MEDIUM", action: row.audit.action, message: "A marketplace account role was changed.", count: 1, actor: row.actor, firstAt: row.audit.createdAt, lastAt: row.audit.createdAt }); } return alerts.slice(0, 50); };

